#include <stdio.h>
#include <string.h>

int soundex_digit(char c) {
    switch(c) {
        case 'B':
        case 'F':
        case 'P':
        case 'V':
            return 1;
        case 'C':
        case 'G':
        case 'J':
        case 'K':
        case 'Q':
        case 'S':
        case 'X':
        case 'Z':
            return 2;
        case 'D':
        case 'T':
            return 3;
        case 'L':
            return 4;
        case 'M':
        case 'N':
            return 5;
        case 'R':
            return 6;
        default:
            return 0;
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("EMPTY\n");
        return 0;
    }
    char *str = argv[1];
    int len = strlen(str);
    char soundex[5] = {0};
    soundex[0] = str[0];
    int soundex_digit_count = 1;
    for (int i = 1; i < len; i++) {
        int digit = soundex_digit(str[i]);
        if (digit != 0 && (soundex_digit_count == 1 || digit != soundex_digit(str[soundex_digit_count - 1]))) {
            soundex[soundex_digit_count++] = digit + '0';
            if (soundex_digit_count == 4) break;
        }
    }
    printf("%s\n", soundex);
    return 0;
}
